const express = require('express');
const { fork } = require('child_process');
const path = require('path');
const { PayrollRun } = require('../models/payrollRun');

const app = express();

app.post('/api/payroll/reports/:payrollRunId/pdf', async (req, res) => {
  if (!req.user || !req.user.companyId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Strictly assert that user is an HR admin and the run belongs to their company
  if (!req.user.roles || !req.user.roles.includes('HR_ADMIN')) {
    return res.status(403).json({ error: 'HR Administrator permissions required' });
  }

  const payrollRun = await PayrollRun.findOne({
    where: {
      id: req.params.payrollRunId,
      companyId: req.user.companyId
    }
  });

  if (!payrollRun) {
    return res.status(404).json({ error: 'Payroll run not found or unauthorized' });
  }

  const workerScript = path.join(__dirname, 'workers', 'payrollPdfGenerator.js');
  const child = fork(workerScript);

  child.send({
    payrollRunId: req.params.payrollRunId,
    companyId: req.user.companyId
  });

  child.on('message', (msg) => {
    if (msg.success) {
      res.json({
        message: 'Payroll PDF generated successfully',
        downloadUrl: msg.pdfLocation
      });
    } else {
      res.status(500).json({ error: msg.error });
    }
  });
});

app.listen(5001);
